#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef __CUDA_ARCH__
#define __CUDA_ARCH__ 0
#endif

// -----------------------------------------------------------------------------
// warp reduction utilities (float)
// -----------------------------------------------------------------------------
__inline__ __device__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = warpSize / 2; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}
__inline__ __device__ float warp_reduce_sum_sq(float val) {
    #pragma unroll
    for (int offset = warpSize / 2; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// -----------------------------------------------------------------------------
// GroupNorm kernel: one block per (batch, group)
// -----------------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void groupnorm_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N, int C, int H, int W,
    int num_groups)
{
    const int HW = H * W;
    const int C_per_group = C / num_groups;
    const int grp_id = blockIdx.x;               // 0 .. N*num_groups-1
    const int n = grp_id / num_groups;
    const int g = grp_id % num_groups;
    const int channel_start = g * C_per_group;
    const int group_elem = C_per_group * HW;     // elements handled by this block

    // -------------------------------------------------------------------------
    // load affine parameters for this group into shared memory (once per block)
    // -------------------------------------------------------------------------
    __shared__ __half w_shared[64];
    __shared__ __half b_shared[64];
    if (threadIdx.x < C_per_group) {
        w_shared[threadIdx.x] = weight[channel_start + threadIdx.x];
        b_shared[threadIdx.x] = bias[channel_start + threadIdx.x];
    }
    __syncthreads();

    // -------------------------------------------------------------------------
    // first pass: compute mean and variance (sum & sumsq)
    // -------------------------------------------------------------------------
    float sum = 0.0f;
    float sumsq = 0.0f;

    // each thread walks over its slice of the group
    for (int idx = threadIdx.x; idx < group_elem; idx += BLOCK_SIZE) {
        int c_offset = idx / HW;           // 0 .. C_per_group-1
        int spatial_idx = idx % HW;        // 0 .. HW-1

        // linear offset into the input tensor
        // ((n*C + (channel_start + c_offset)) * HW) + spatial_idx
        int offset = ((n * C + channel_start + c_offset) * HW) + spatial_idx;
        float val = __half2float(input[offset]);
        sum   += val;
        sumsq += val * val;
    }

    // -------------------------------------------------------------------------
    // warp‑level reduction
    // -------------------------------------------------------------------------
    float warp_sum   = warp_reduce_sum(sum);
    float warp_sumsq = warp_reduce_sum_sq(sumsq);

    // store per‑warp results in shared memory
    __shared__ float block_sum[32];
    __shared__ float block_sumsq[32];
    const int lane   = threadIdx.x % warpSize;
    const int warpId = threadIdx.x / warpSize;

    if (lane == 0) {
        block_sum[warpId]   = warp_sum;
        block_sumsq[warpId] = warp_sumsq;
    }
    __syncthreads();

    // final reduction by first warp
    float total_sum = 0.0f;
    float total_sumsq = 0.0f;
    if (warpId == 0) {
        float val = (lane < (BLOCK_SIZE / warpSize)) ? block_sum[lane] : 0.0f;
        float val2 = (lane < (BLOCK_SIZE / warpSize)) ? block_sumsq[lane] : 0.0f;
        total_sum   = warp_reduce_sum(val);
        total_sumsq = warp_reduce_sum_sq(val2);
    }
    __syncthreads();

    // broadcast mean & inv_std to all threads
    float mean, inv_std;
    const float eps = 1e-5f;
    if (threadIdx.x == 0) {
        float m = total_sum / group_elem;
        float v = total_sumsq / group_elem - m * m;
        v = v > 0.0f ? v : 0.0f;
        float i_std = rsqrtf(v + eps);
        mean = m;
        inv_std = i_std;
    }
    __syncthreads();
    mean = __shfl_sync(0xffffffff, mean, 0);
    inv_std = __shfl_sync(0xffffffff, inv_std, 0);

    // -------------------------------------------------------------------------
    // second pass: normalize and apply affine
    // -------------------------------------------------------------------------
    for (int idx = threadIdx.x; idx < group_elem; idx += BLOCK_SIZE) {
        int c_offset = idx / HW;
        int spatial_idx = idx % HW;
        int offset = ((n * C + channel_start + c_offset) * HW) + spatial_idx;
        float val = __half2float(input[offset]);

        float norm = (val - mean) * inv_std;
        float w = __half2float(w_shared[c_offset]);
        float b = __half2float(b_shared[c_offset]);
        float out = norm * w + b;
        output[offset] = __float2half(out);
    }
}

// -----------------------------------------------------------------------------
// wrapper
// -----------------------------------------------------------------------------
torch::Tensor groupnorm_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t num_groups)
{
    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    auto output = torch::empty_like(input);
    const int total_groups = N * num_groups;
    constexpr int BLOCK_SIZE = 256;
    dim3 block(BLOCK_SIZE);
    dim3 grid(total_groups);

    groupnorm_kernel<BLOCK_SIZE><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C, H, W, static_cast<int>(num_groups));

    return output;
}
